def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]] == color:
                        seen.add(q); stack.append(q)
            r0, c0 = min(y for y,x in cells), min(x for y,x in cells)
            # Components are solid monochrome objects; preserve their cell geometry.
            shape = [(y-r0, x-c0) for y,x in cells]
            objs.append((c0, r0, color, shape))
    objs.sort(key=lambda o: (o[0], o[1]))
    out = [[0]*w for _ in range(h)]
    anchor_r = anchor_c = 0
    for i, (_, _, color, shape) in enumerate(objs):
        if i == 0:
            top, left = 0, 0
        else:
            top, left = anchor_r, anchor_c
        for dy, dx in shape:
            y, x = top+dy, left+dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
        maxdy = max(dy for dy,dx in shape)
        maxdx = max(dx for dy,dx in shape)
        anchor_r, anchor_c = top+maxdy, left+maxdx
    return out
